// Dipakai pada halaman /nota/isi (pembayaran satu nota) dan /nota/bayar (seluruh pembayaran)
const $tabelBayar = $('#tabelBayar'),
    $formBayar = $('#formBayar'),
    $modalBayar = $('#modalBayar'),
    bayarCek = CirebonwebForm.FormCek($formBayar);

// Kembalian = uang diterima - jumlah bayar (tidak boleh negatif)
function hitungKembalian() {
    const diterima = CirebonwebFormat.unRupiah($('#bayar_diterima').val()) || 0;
    const jumlah = CirebonwebFormat.unRupiah($('#bayar_jumlah').val()) || 0;

    $('#bayar_kembalian').val(CirebonwebFormat.Rupiah(Math.max(0, diterima - jumlah)));
}

$(function () {
    if (!$tabelBayar.length) return;

    $tabelBayar.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${bayarUrl}/tabel`,
            type: 'POST',
            data: function (d) {
                if (idNota > 0) d.nota_id = idNota;
            }
        },
        autoWidth: false,
        responsive: true,
        searching: false,
        ordering: false,
        dom: 'Brtip',
        buttons: [
            {
                text: 'Reload',
                action: function (e, dt) {
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 3], className: 'dt-body-center' },
            { targets: [4, 5, 6], className: 'dt-body-right', orderable: false },
            { targets: [4, 5, 6], render: CirebonwebFormat.RupiahTabel },
            { targets: [2, 8, 9], render: (data) => CirebonwebFormat.Tanggal(data) },
            { targets: 10, orderable: false, render: (data) => (idNota > 0 && statusNota === 3) ? 'Null' : data },
        ]
    });

    $('.tanggal').datepicker({ dateFormat: 'dd-mm-yy' });

    $(document).on('input change', '#bayar_diterima, #bayar_jumlah', hitungKembalian);

    $modalBayar.on('shown.bs.modal', function () { bayarCek.resetInitial(); })
        .on('hidden.bs.modal', function () { CirebonwebForm.FormReset(this); });
});

// Ringkasan nota dihitung oleh trigger; di halaman nota diperbarui lewat AJAX
function segarkanHalaman() {
    if (idNota > 0 && typeof segarkanRingkasanNota === 'function') {
        segarkanRingkasanNota();
    }
}

// Form Submit (Insert/Update)
function simpanBayar(id) {
    if (!$formBayar.length) return;

    const isEdit = id > 0;
    const $modalTitle = $modalBayar.find('.modal-title'),
        $btnSubmit = $('#btnSubmitBayar'),
        postUrl = `${bayarUrl}/simpan`;

    if (isEdit) {
        CirebonwebForm.FormFetch(`${bayarUrl}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            const data = response.data;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $formBayar.find('#bayar_id').val(data.id);
            $formBayar.find('#bayar_nota_id').val(data.nota_id);
            CirebonwebFormat.isoTanggal('bayar_tanggal', data.tanggal);
            $formBayar.find('#bayar_metode').val(data.metode);
            $formBayar.find('#bayar_diterima').val(CirebonwebFormat.Rupiah(data.diterima));
            $formBayar.find('#bayar_jumlah').val(CirebonwebFormat.Rupiah(data.jumlah));
            hitungKembalian();
            $modalBayar.modal('show');
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        // FormReset mengosongkan input hidden, jadi id nota dipasang ulang
        $formBayar.find('#bayar_nota_id').val(idNota);
        $formBayar.find('#bayar_tanggal').val(CirebonwebFormat.Tanggal(new Date(), 'tanggal'));
        $formBayar.find('#bayar_diterima, #bayar_jumlah').val(CirebonwebFormat.Rupiah(0));
        $formBayar.find('#bayar_kembalian').val('0');
        $modalBayar.modal('show');
    }

    $formBayar.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            nota_id: { required: true, digits: true },
            tanggal: { required: true },
            diterima: { required: true },
            jumlah: { required: true },
        },
        submitHandler: function () {
            if (!bayarCek.isChanged()) return false;

            const data = $formBayar.serializeArray();
            data.forEach(function (item) {
                if (['diterima', 'jumlah'].includes(item.name)) {
                    item.value = CirebonwebFormat.unRupiah(item.value);
                } else if (item.name === 'tanggal') {
                    item.value = CirebonwebFormat.sqlTanggal(item.value);
                }
            });

            CirebonwebForm.FormFetch(postUrl, data, 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalBayar.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () {
                        $tabelBayar.DataTable().ajax.reload(null, false);
                        segarkanHalaman();
                    });
            });
            return false;
        }
    }));
}

// Form Submit (Delete)
function hapusBayar(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${bayarUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () {
                    $tabelBayar.DataTable().ajax.reload(null, false);
                    segarkanHalaman();
                });
        });
    });
}
